"この角度はインピンジメントゾーンを避けるため、通常のラテラルレイズより肩に優しいことが多いです。",
"肩の高さまでのみ上げましょう。それ以上上げても効果はなく負担が増えるだけです。",
"ラテラルレイズより軽い重量を使いましょう。斜めの軌道は力学的に効率が落ちます。",
"肘は軽く曲げたまま、勢いを使って振り上げないようにしましょう。"
