"腕を上へ外へ上げ、親指をリードにして頭上に大きな「Y」の形を作りましょう。",
"肘をロックせず、動作中ずっと軽く曲げたままにしましょう。",
"この種目は僧帽筋下部と後部三角筋を同時に鍛え、姿勢改善に効果的な仕上げ種目です。",
"軽い重量を使いましょう。これはコントロールと位置取りの種目で、重い挙上種目ではありません。",
"腕を上げるときに肩が耳の方へすくまないようにしましょう。"
