"上腕は垂直に保ち、動作中は完全に静止させます。",
"肘を曲げ、両方のダンベルを頭の横に向かって下ろします。",
"肘を伸ばして、開始姿勢まで腕を戻します。",
"上腕が動いてしまう場合は重量を下げましょう。この種目は肘の曲げ伸ばしだけで行うのが正解です。"
