"上腕を動かさずに、バーを胸の上あたりの高さまで巻き上げます。",
"一番上で上腕二頭筋を一瞬しっかり収縮させます。",
"毎レップ、コントロールしながら腕が完全に伸びる位置まで下ろします。"
