"体幹を締め、上体を完全に静止させます。",
"バーを前方かつ上方向にまっすぐ持ち上げ、腕が床と平行になるまで上げます。",
"コントロールしながら弧を描くように、バーを太もものところまで下ろします。",
"肘を曲げたり上体を揺らして助けたりせず、三角筋前部の力だけで持ち上げます。"
