"お尻を締めながら腰を持ち上げ、肩から膝まで体が一直線になるようにします。",
"一番上で1〜2秒収縮をキープし、腰を床の少し上まで下ろします。完全には休めません。",
"毎レップ、床の少し手前で止めることで、お尻への負荷を保ちます。"
