"背中をまっすぐにして上体を約45度前に倒し、右手でケトルベルを持って腕をまっすぐ下に垂らします。",
"肘を腰の方向に引きながら、ケトルベルを体の横に沿って引き上げます。",
"ケトルベルが肋骨の下あたりの横に来て、肘が背中の後ろで上を向いたところで止めます。",
"腕が伸びるまでゆっくり下ろします。全ての回数を終えたら、反対側も行います。"
